                self.try_combine(slog);
                iter = 0;
            }
            let deq_resp_result = context.dequeue_response(context_ghost_new);
            r = deq_resp_result.0;
            context_ghost_new = deq_resp_result.1;
            iter = iter + 1;
        }
        let r = r.unwrap();
        (r, context_ghost_new)
    }
